package com.opentv.app.ui;
import android.os.*;import android.view.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import androidx.media3.common.*;import androidx.media3.datasource.DefaultHttpDataSource;import androidx.media3.exoplayer.ExoPlayer;import androidx.media3.exoplayer.source.DefaultMediaSourceFactory;import androidx.media3.ui.PlayerView;import com.opentv.app.R;import com.opentv.app.data.*;import com.opentv.app.model.Channel;import com.opentv.app.util.LogoLoader;import java.util.*;import java.util.concurrent.*;
public class PlayerActivity extends AppCompatActivity{ExoPlayer player;Channel channel;FavoritesStore fav;TextView name,meta,source,star,error,zap;ImageView logo;View info;final Handler h=new Handler(Looper.getMainLooper());final List<Channel>channels=new ArrayList<>();int index=-1;final ExecutorService ex=Executors.newSingleThreadExecutor();String playlist,label;
protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_player);fav=new FavoritesStore(this);channel=new Channel("",getIntent().getStringExtra("name"),getIntent().getStringExtra("url"),getIntent().getStringExtra("logo"),getIntent().getStringExtra("group"),getIntent().getStringExtra("country"),getIntent().getStringExtra("language"));playlist=getIntent().getStringExtra("playlist_url");label=getIntent().getStringExtra("source_label");info=findViewById(R.id.playerInfo);name=findViewById(R.id.playerName);meta=findViewById(R.id.playerMeta);source=findViewById(R.id.playerSource);star=findViewById(R.id.playerFavorite);error=findViewById(R.id.playerError);zap=findViewById(R.id.channelZap);logo=findViewById(R.id.playerLogo);DefaultHttpDataSource.Factory http=new DefaultHttpDataSource.Factory().setUserAgent("OpenTV/1.1 AndroidTV").setAllowCrossProtocolRedirects(true);player=new ExoPlayer.Builder(this).setMediaSourceFactory(new DefaultMediaSourceFactory(http)).build();((PlayerView)findViewById(R.id.playerView)).setPlayer(player);player.addListener(new Player.Listener(){public void onPlayerError(PlaybackException e){error.setText("Stream unavailable\nPress ▲ or ▼ for another channel");error.setVisibility(View.VISIBLE);}});tune(channel);if(playlist!=null)ex.execute(()->{try{List<Channel>x=new PlaylistRepository(this).load(playlist,false);h.post(()->{channels.addAll(x);for(int i=0;i<x.size();i++)if(x.get(i).url.equals(channel.url))index=i;});}catch(Exception ignored){}});}
void tune(Channel c){channel=c;name.setText(c.name);meta.setText(c.subtitle());source.setText((label==null?"LIVE TV":label.toUpperCase())+" • LIVE");star.setText(fav.contains(c.url)?"★":"☆");LogoLoader.load(logo,c.logo);error.setVisibility(View.GONE);player.setMediaItem(MediaItem.fromUri(c.url));player.prepare();player.play();info.setVisibility(View.VISIBLE);}
void change(int d){if(channels.isEmpty())return;if(index<0)index=0;index=(index+d+channels.size())%channels.size();tune(channels.get(index));zap.setText(channel.name);zap.setVisibility(View.VISIBLE);h.postDelayed(()->zap.setVisibility(View.GONE),1500);}
public boolean onKeyLongPress(int k,KeyEvent e){if(k==KeyEvent.KEYCODE_DPAD_CENTER||k==KeyEvent.KEYCODE_ENTER){fav.toggle(channel);star.setText(fav.contains(channel.url)?"★":"☆");return true;}return super.onKeyLongPress(k,e);}public boolean onKeyDown(int k,KeyEvent e){if(k==KeyEvent.KEYCODE_DPAD_UP||k==KeyEvent.KEYCODE_CHANNEL_UP){change(-1);return true;}if(k==KeyEvent.KEYCODE_DPAD_DOWN||k==KeyEvent.KEYCODE_CHANNEL_DOWN){change(1);return true;}if(k==KeyEvent.KEYCODE_DPAD_CENTER||k==KeyEvent.KEYCODE_ENTER||k==KeyEvent.KEYCODE_INFO){info.setVisibility(View.VISIBLE);return true;}return super.onKeyDown(k,e);}protected void onDestroy(){ex.shutdownNow();if(player!=null)player.release();super.onDestroy();}}
